-- ============================================================================
-- E-Library demo catalogue: 100 books spanning ~40 subject areas.
--
-- Broad topical coverage is the point: semantic search can only match what is
-- in the catalogue, so a wide spread means most reasonable searches land on
-- something relevant. Descriptions and tags are deliberately keyword-rich
-- because those fields are what actually get embedded (see
-- RecommendationService.initialize_vector_store).
--
-- Safe to re-run: ISBN is UNIQUE, so ON DUPLICATE KEY UPDATE refreshes rows
-- instead of duplicating them.
--
-- created_at / updated_at / available_copies / is_active / rating are set
-- explicitly and must stay that way — the Book response schema requires them,
-- and NULLs there make GET /api/v1/books/ fail with a 500.
--
-- ISBNs are illustrative demo values, not verified catalogue numbers.
--
-- RUN IT
--   Windows:  mysql -u root -p elibrary_db < seed_books.sql
--   macOS:    mysql -u root elibrary_db < seed_books.sql
--   phpMyAdmin / XAMPP: select elibrary_db, Import tab, choose this file.
--
-- AFTERWARDS: restart the backend. The vector store is built once per process
-- and cached, so a running server will not see these rows until it restarts.
-- ============================================================================

USE elibrary_db;

INSERT INTO books
    (isbn, title, author, publisher, publication_year, category, description,
     total_copies, available_copies, is_active, language, pages, rating, tags,
     created_at, updated_at)
VALUES
