-- The legacy VALUES(col) form is used deliberately instead of the newer
-- "AS new" row alias: the alias syntax needs MySQL 8.0.19+ and is not supported
-- by MariaDB, which is what XAMPP ships on Windows.
ON DUPLICATE KEY UPDATE
    title             = VALUES(title),
    author            = VALUES(author),
    publisher         = VALUES(publisher),
    publication_year  = VALUES(publication_year),
    category          = VALUES(category),
    description       = VALUES(description),
    total_copies      = VALUES(total_copies),
    available_copies  = VALUES(available_copies),
    is_active         = VALUES(is_active),
    language          = VALUES(language),
    pages             = VALUES(pages),
    rating            = VALUES(rating),
    tags              = VALUES(tags),
    updated_at        = NOW();

-- Confirm what landed.
SELECT COUNT(*) AS active_books FROM books WHERE is_active = 1;
SELECT category, COUNT(*) AS books FROM books WHERE is_active = 1 GROUP BY category ORDER BY category;
